import React from 'react';
import { Row, TableDispatch } from 'react-table';

import { DEFAULT_VARIANT_CONFIG } from '../DataTable/constants.js';
import { ColumnMinInstance } from '../types/internal-table-types.js';
import type {
  TableVariantConfig,
  TableColumn,
} from '../types/shared-table-types.js';
import type { ColumnVisibilityConfig } from '../types/table-config-types.js';

interface DataTableContextType {
  columns: TableColumn[];
  instanceColumns?: ColumnMinInstance[];
  columnVisibility: ColumnVisibilityConfig;
  onVisibilityChange?: (visibility: ColumnVisibilityConfig) => void;
  data: any[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  hiddenColumns: string[];
  page: Row<any>[]; // eslint-disable-line @typescript-eslint/no-explicit-any
  selectableRowsActive: boolean;
  paginationActive: boolean;
  variant: TableVariantConfig;
  onDataTableFontStyleChange?: (fontStyle: 'text' | 'code') => void;
  onDataTableColumnFontStyleChange?: (updatedColumn: ColumnMinInstance) => void;
  lineWrap: boolean;
  allColumns?: ColumnMinInstance[];
  visibleColumns?: ColumnMinInstance[];
  visibleOrderingColumns?: ColumnMinInstance[];
  allOrderingColumns?: ColumnMinInstance[];
  onColumnLineWrapChange?: (updatedColumn: ColumnMinInstance) => void;
  dispatch: TableDispatch;
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  currentSelectedRows: Row<any>[];
  defaultColumnOrder?: string[];
  columnOrder?: string[];
  onColumnOrderChange: (columnOrder: string[]) => void;
  onColumnOrderChangeProp?: (columnOrder: string[]) => void;
  onDownloadData?: (subset: 'all' | 'page' | 'selected') => void;
}

const DEFAULT_CONTEXT: DataTableContextType = {
  columns: [],
  instanceColumns: [],
  columnVisibility: {},
  onVisibilityChange: (visibility: ColumnVisibilityConfig) => {
    // Do nothing
  },
  hiddenColumns: [],
  data: [],
  page: [],
  selectableRowsActive: false,
  paginationActive: false,
  variant: DEFAULT_VARIANT_CONFIG,
  onDataTableFontStyleChange: (fontStyle: 'text' | 'code') => {
    // Do nothing
  },
  onDataTableColumnFontStyleChange: (updatedColumn: ColumnMinInstance) => {
    // Do nothing
  },
  lineWrap: false,
  allColumns: [],
  visibleColumns: [],
  visibleOrderingColumns: [],
  allOrderingColumns: [],
  dispatch: () => {
    /* noop */
  },
  currentSelectedRows: [],
  defaultColumnOrder: [],
  columnOrder: [],
  onColumnOrderChange: () => {
    // Do nothing
  },
  onColumnOrderChangeProp: () => {
    // Do nothing
  },
};

export const DataTableContext =
  React.createContext<DataTableContextType>(DEFAULT_CONTEXT);
